using System;
using System.Collections.Generic;
using System.Linq;

namespace NeisAnalyzer
{
    /// <summary>결과 엑셀에 들어가는 모든 지표의 뜻과 읽는 법. 숫자만 보고도 해석할 수 있게 쉬운 말로 쓴다.</summary>
    public class Term
    {
        public string Key;        // 코드에서 부르는 이름
        public string Name;       // 표에 보이는 이름
        public string What;       // 무엇인가 (한두 문장)
        public string Range;      // 값의 범위
        public string Better;     // 방향(높고 낮음의 뜻)
        public string HowToRead;  // 수치 구간별 읽는 법
        public string Caution;    // 주의할 점
    }

    public static class Glossary
    {
        public static readonly List<Term> Terms = new List<Term>
        {
            new Term { Key="평균", Name="평균", What="학생들 점수를 모두 더해 인원수로 나눈 값. 반이나 학년의 전체적인 수준을 나타냅니다.", Range="0 ~ 만점", Better="높을수록 전체 수준이 높음",
                HowToRead="학교 지필고사는 보통 55~75점 사이에 많이 분포합니다. 반 평균끼리 5점 이상 차이 나면 눈여겨볼 만합니다.", Caution="아주 낮은 학생 몇 명이 평균을 많이 끌어내릴 수 있으므로 중앙값과 함께 보세요." },
            new Term { Key="중앙값", Name="중앙값", What="점수를 높은 순으로 줄 세웠을 때 한가운데 학생의 점수. '보통 학생'의 점수라고 보면 됩니다.", Range="0 ~ 만점", Better="높을수록 보통 학생의 수준이 높음",
                HowToRead="평균보다 중앙값이 많이 높으면 아주 낮은 점수의 학생이 일부 있다는 뜻이고, 중앙값이 평균보다 낮으면 아주 높은 점수의 학생이 일부 있다는 뜻입니다.", Caution="" },
            new Term { Key="표준편차", Name="표준편차", What="점수가 평균에서 얼마나 넓게 퍼져 있는지 나타내는 값. 학생 간 실력 차이의 크기입니다.", Range="0 이상", Better="좋고 나쁨이 아니라 '퍼짐의 정도'",
                HowToRead="100점 만점 기준으로 10점 이하면 점수가 비슷비슷하게 모여 있고, 15~20점이면 보통, 25점 이상이면 상·하위 차이가 매우 큰 편입니다.", Caution="반별로 표준편차가 유난히 크면 그 반 안에 수준 차이가 커서 수업 난이도 맞추기가 어려운 반입니다. 이 프로그램은 모집단 방식(N으로 나눔, KICE 분석 프로그램과 같음)으로 계산하므로 엑셀 STDEV.S보다 조금 작게 나옵니다." },
            new Term { Key="성취도별통계", Name="성취도별 인원·평균·표준편차", What="성취도 A~E 집단마다 몇 명인지, 그 집단의 최종 점수 평균과 표준편차, 수행·지필 평균은 얼마인지 정리한 표. 교육과정평가원(KICE) 성취도분석표와 같은 구성입니다.", Range="인원 0 이상, 점수 0 ~ 만점", Better="좋고 나쁨이 아니라 집단별 특징을 보는 표",
                HowToRead="E 집단의 평균이 매우 낮고(40점 이하) 표준편차가 크면 E 안에서도 격차가 커서 기초 학습 지원 대상을 따로 골라야 합니다. A 집단의 표준편차가 3 이하이면 상위권이 촘촘히 몰려 있어 수행평가 1점 차이로 등수가 많이 바뀝니다.", Caution="성취도는 최종 점수(수행+지필) 기준입니다. 인원이 5명 미만인 집단의 평균·표준편차는 큰 의미가 없습니다." },
            new Term { Key="성취도별문항", Name="성취도별 문항 정답률", What="같은 문항을 성취도 A·B·C·D·E 집단이 각각 얼마나 맞혔는지 비교한 것.", Range="0% ~ 100%", Better="A에서 E로 갈수록 정답률이 차례로 낮아지는 것이 정상",
                HowToRead="정상적인 문항은 A 집단 정답률이 가장 높고 E로 갈수록 낮아집니다. 낮은 성취도 집단이 높은 집단보다 15%p 이상 많이 맞힌 문항은 '수준 역전'으로 표시되며, 정답 입력 오류·중의적 선택지·찍어서 맞히기 쉬운 문항일 가능성이 있어 문항을 검토해야 합니다. E 집단 정답률이 50%를 넘으면 그 문항은 기초 개념 문항입니다.", Caution="두 집단 모두 5명 이상일 때만 역전을 판정합니다. 성취도는 수행평가를 포함한 최종 점수 기준이므로, 지필 점수로만 나눈 집단과는 다를 수 있습니다." },
            new Term { Key="최고최저", Name="최고점 / 최저점", What="가장 높은 점수와 가장 낮은 점수.", Range="0 ~ 만점", Better="최고점은 높을수록, 최저점은 높을수록 학급 전체가 고르게 잘한 것",
                HowToRead="최저점이 매우 낮은 학생은 '관심 학생' 시트에 성취도 E로 나타납니다.", Caution="" },
            new Term { Key="성취도", Name="성취도 (A~E)", What="최종 점수를 기준 점수에 따라 A·B·C·D·E 다섯 단계로 나눈 것. 중학교 성적표에 기록되는 평가 등급입니다.", Range="A ~ E", Better="A에 가까울수록 높은 성취",
                HowToRead="기본 기준은 A 90점 이상, B 80점 이상, C 70점 이상, D 60점 이상, 그 미만 E입니다. 학년 전체에서 A와 E가 각각 10~20% 정도면 흔한 분포입니다. E가 30%를 넘으면 시험이 어려웠거나 학습 결손이 큰 것입니다.", Caution="성취도는 '최종 점수를 정수로 반올림한 값'으로 판정하는 것이 기본 설정입니다(설정에서 변경 가능). 89.5점은 90점으로 반올림되어 A가 됩니다." },
            new Term { Key="성취도경계", Name="성취도 경계", What="최종 점수가 성취도 기준 점수(90·80·70·60)에서 ±1점 안에 있는 학생.", Range="-", Better="경계 학생은 적을수록 성취도 판정이 안정적",
                HowToRead="예) 'A 경계(-0.4)'는 A 기준보다 0.4점 모자란다는 뜻입니다. 반올림 규정이나 수행평가 점수 1점 차이로 성취도가 바뀔 수 있는 학생이니 점수 입력에 오류가 없는지 한 번 더 확인하세요.", Caution="" },
            new Term { Key="등수", Name="학년 등수 / 반 등수", What="최종 점수가 높은 순서. 동점이면 같은 등수를 주고, 다음 등수는 동점자 수만큼 건너뜁니다(예: 1, 1, 3).", Range="1 ~ 인원", Better="숫자가 작을수록 상위",
                HowToRead="등수는 교사용 참고 자료입니다. 중학교 성적표에는 등수를 기재하지 않습니다.", Caution="면제·결시로 제외된 학생은 등수가 없습니다." },
            new Term { Key="정답률", Name="정답률 (문항 난이도)", What="그 문항을 맞힌 학생의 비율. 고전검사이론에서는 이 값을 '문항 난이도(P)'라고 부릅니다.", Range="0% ~ 100%", Better="높을수록 쉬운 문항 (좋고 나쁨이 아님)",
                HowToRead="80% 이상이면 쉬움, 50~80%이면 보통, 50% 미만이면 어려움으로 표시합니다. 시험 전체로는 쉬움·보통·어려움이 골고루 섞여 있고 평균 정답률이 60~70% 정도면 적절한 난이도입니다.", Caution="정답률 95% 이상 문항은 거의 전원이 맞혀 실력을 가르지 못하고, 25% 미만이면 찍어서 맞히는 수준(5지선다 20%)에 가까워 문항이나 수업 내용을 점검해야 합니다." },
            new Term { Key="오답률", Name="오답률 / 무응답률 / 복수답안", What="틀린 번호를 고른 비율, 아무 표시도 하지 않은 비율, 두 개 이상 표시한 비율.", Range="0% ~ 100%", Better="무응답·복수답안은 낮을수록 좋음",
                HowToRead="무응답이 특정 문항에만 몰려 있으면 문제가 지나치게 어렵거나 시간이 부족했던 뒷번호일 수 있습니다. 특정 학생에게 무응답이 많으면 '관심 학생'에 표시됩니다.", Caution="" },
            new Term { Key="변별도", Name="변별도 (상위-하위 27% 정답률 차이)", What="잘하는 학생과 못하는 학생을 그 문항이 얼마나 잘 갈라 주는지 나타내는 값. 지필 총점 상위 27% 학생의 정답률에서 하위 27% 학생의 정답률을 뺀 것입니다.", Range="-1 ~ +1", Better="높을수록 좋음 (0.30 이상이면 좋은 문항)",
                HowToRead="0.40 이상: 매우 좋은 문항 / 0.30~0.39: 좋은 문항 / 0.20~0.29: 보통(다듬으면 좋음) / 0.10~0.19: 낮음(검토 필요) / 0.10 미만: 변별이 거의 안 됨 / 음수: 못하는 학생이 더 많이 맞힌 것이므로 정답 입력 오류나 문항 오류를 반드시 확인하세요.", Caution="거의 모두 맞히거나 거의 모두 틀린 문항(정답률 95% 이상 또는 15% 이하)은 변별도가 낮게 나오는 것이 자연스럽습니다. 인원이 30명 미만이면 값이 흔들릴 수 있습니다." },
            new Term { Key="상하위정답률", Name="상위 27% / 하위 27% 정답률", What="지필 총점이 높은 쪽 27% 학생들과 낮은 쪽 27% 학생들이 각각 그 문항을 맞힌 비율. 변별도를 구하는 재료입니다.", Range="0% ~ 100%", Better="상위는 높고 하위는 낮을수록 잘 가르는 문항",
                HowToRead="두 값이 비슷하면 그 문항은 실력과 상관없이 맞히거나 틀린다는 뜻입니다. 상위권 정답률이 하위권보다 낮으면(변별도 음수) 문항을 점검하세요.", Caution="27%는 교육측정에서 관례적으로 쓰는 비율입니다." },
            new Term { Key="점이연상관", Name="문항-총점 상관 (점이연 상관)", What="그 문항을 맞힌 학생(1)과 틀린 학생(0)의 구분이 지필 총점과 얼마나 같이 움직이는지 나타내는 상관계수. 변별도를 다른 방법으로 계산한 것이라고 보면 됩니다.", Range="-1 ~ +1", Better="높을수록 좋음 (0.30 이상이면 좋은 문항)",
                HowToRead="0.30 이상: 좋음 / 0.20~0.29: 보통 / 0.20 미만: 낮음(검토) / 음수: 문항·정답 점검. 변별도와 함께 보고 둘 다 낮으면 문항을 손보는 것이 좋습니다.", Caution="'-'로 표시되면 전원이 맞히거나 틀려 계산할 수 없는 문항입니다." },
            new Term { Key="난이도구분", Name="난이도 구분 (쉬움·보통·어려움)", What="정답률을 세 단계로 나눈 표시.", Range="쉬움 / 보통 / 어려움", Better="어느 하나가 좋은 것이 아니라 세 가지가 골고루 섞인 것이 좋음",
                HowToRead="기본 기준은 정답률 80% 이상 쉬움, 50% 이상 보통, 50% 미만 어려움입니다. 좋은 시험은 어려운 문항이 전체의 20~30%, 쉬운 문항이 20~30%, 나머지가 보통인 구성입니다.", Caution="" },
            new Term { Key="매력적오답", Name="매력적 오답", What="틀린 학생들이 가장 많이 고른 오답 번호와 그 비율.", Range="번호, 0% ~ 100%", Better="선택 비율이 높을수록 많은 학생이 같은 오개념을 가진 것",
                HowToRead="30% 이상의 학생이 같은 오답을 골랐다면 많은 학생이 공통으로 갖고 있는 오개념일 가능성이 큽니다. 그 선택지 내용을 수업에서 다시 짚어 주면 효과적입니다. 반대로 아무도 고르지 않은 선택지는 오답으로서 역할을 못 하는 것입니다.", Caution="" },
            new Term { Key="답지반응", Name="답지 반응 분포", What="각 문항에서 ①~⑤ 각 번호를 고른 학생의 비율.", Range="0% ~ 100%", Better="정답 비율이 가장 높고 오답들이 고르게 나뉠수록 잘 만든 문항",
                HowToRead="정답 칸(파란색)이 가장 높고 나머지 오답에 적당히 분산되어 있으면 잘 만든 문항입니다. 오답 하나(빨간색)에 정답만큼 몰려 있으면 헷갈리는 선택지이거나 오개념입니다.", Caution="정오표에는 틀린 학생이 고른 번호만 있으므로, 맞은 학생은 정답 번호를 고른 것으로 계산했습니다." },
            new Term { Key="KR20", Name="시험 신뢰도 (KR-20)", What="시험 전체가 학생의 실력을 얼마나 일관되게 재는지 나타내는 값. 같은 학생이 비슷한 시험을 다시 봐도 비슷한 점수가 나올지를 뜻합니다. 선택형 문항 전체로 계산합니다.", Range="0 ~ 1", Better="높을수록 좋음 (0.70 이상이면 학교 시험으로 무난)",
                HowToRead="0.90 이상: 매우 높음(대규모 표준화 시험 수준) / 0.80~0.89: 양호 / 0.70~0.79: 보통(학교 시험으로 무난) / 0.60~0.69: 낮은 편(문항 점검 권장) / 0.60 미만: 낮음(변별도 낮은 문항이 많다는 뜻).", Caution="문항 수가 적을수록, 학생 수준이 비슷할수록 낮게 나오는 경향이 있습니다. 서답형 점수는 계산에 포함되지 않습니다." },
            new Term { Key="반별문항", Name="반별 문항 정답률 비교", What="같은 문항을 반별로 맞힌 비율을 학년 전체와 비교한 것.", Range="0% ~ 100%", Better="학년 정답률과 차이가 작을수록 반 간 수업 격차가 없는 것",
                HowToRead="학년 정답률보다 15%p 이상 낮은 반-문항(빨간색)은 그 반에서 해당 내용이 덜 다루어졌거나 이해가 부족했을 수 있습니다. 같은 단원의 여러 문항이 한 반에서 함께 낮으면 수업 보완이 필요한 신호입니다.", Caution="한 반 인원이 적으면(20명 미만) 한두 명 차이로도 10%p 이상 움직이므로 지나치게 해석하지 마세요." },
            new Term { Key="상관계수", Name="상관계수 (수행 vs 지필, 중간 vs 기말)", What="두 점수가 얼마나 같은 방향으로 움직이는지 나타내는 값(피어슨 상관계수). 1이면 완전히 같은 순서, 0이면 관련 없음.", Range="-1 ~ +1", Better="높을수록 두 평가가 같은 실력을 재고 있음",
                HowToRead="0.70 이상: 강한 관련(수행 잘하는 학생이 지필도 잘함) / 0.40~0.69: 중간 정도 관련 / 0.20~0.39: 약한 관련 / 0.20 미만: 거의 관련 없음. 수행 vs 지필은 보통 0.4~0.7 사이로 나옵니다.", Caution="수행평가는 만점자가 많아 점수 차이가 작기 때문에 상관이 낮게 나오기 쉽습니다. 낮다고 해서 평가가 잘못된 것은 아닙니다." },
            new Term { Key="상대차이", Name="수행-지필 상대 차이", What="수행 점수와 지필 점수를 각각 100점 만점 비율로 바꿔 뺀 값(수행 − 지필)에서, 학년 평균 차이를 다시 뺀 것.", Range="대략 -60 ~ +60", Better="0에 가까울수록 두 평가가 균형 있음",
                HowToRead="+20 이상: 수행에 비해 지필이 유난히 낮은 학생(시험 불안, 지필 준비 부족 가능성) / -20 이하: 지필에 비해 수행이 유난히 낮은 학생(과제 미제출, 참여 부족 가능성). 상담 참고용입니다.", Caution="학년 평균 차이를 빼는 이유: 수행 점수는 대부분 지필보다 높아서 그냥 빼면 모든 학생이 '지필이 낮음'으로 나오기 때문입니다." },
            new Term { Key="만점자비율", Name="만점자 비율 / 최저점 비율 (수행평가)", What="그 수행 영역에서 만점을 받은 학생 비율과 가장 낮은 점수를 받은 학생 비율.", Range="0% ~ 100%", Better="만점자 비율이 높을수록 그 영역은 학생을 가르지 못함(성취 자체는 좋은 것)",
                HowToRead="만점자 비율이 60%를 넘으면 그 영역은 학생을 거의 가르지 못합니다(대부분 같은 점수). 최저점 비율이 높으면 미제출·불참이 많았던 영역일 수 있습니다.", Caution="수행평가는 성취기준 도달 여부를 보는 평가이므로 만점자가 많은 것 자체는 문제가 아닙니다. 다만 성적 산출 관점에서 변별 참고용입니다." },
            new Term { Key="점수분포", Name="점수 분포 (10점 구간)", What="최종 점수를 10점 단위로 묶어 몇 명씩 있는지 센 것(히스토그램).", Range="-", Better="가운데가 볼록한 종 모양이 전형적, 봉우리가 둘이면 집단이 갈린 것",
                HowToRead="가운데(60~80점)가 볼록하고 양쪽으로 줄어드는 종 모양이면 전형적인 분포입니다. 봉우리가 두 개이면 잘하는 집단과 못하는 집단으로 나뉘어 있다는 뜻입니다. 왼쪽(낮은 점수)에 꼬리가 길면 학습 결손 학생이 일정 수 있다는 뜻입니다.", Caution="" },
            new Term { Key="점수변화", Name="중간 → 기말 점수 변화", What="같은 학생의 두 지필고사 원점수 차이.", Range="-100 ~ +100", Better="+이면 상승",
                HowToRead="±15점 이상이면 '크게 상승/하락'으로 표시합니다. 두 시험의 난이도가 다르면 전체가 함께 오르내리므로, 학년 평균 변화와 비교해서 보세요.", Caution="" },
            new Term { Key="검산", Name="검산", What="정오표의 문항 정오·배점으로 다시 계산한 반별 응시생수·총점·평균을 나이스 일람표의 값과 비교한 것.", Range="일치 / 불일치", Better="모두 '일치'여야 함",
                HowToRead="하나라도 '불일치'이면 파일이 서로 다른 시험·학기의 것이거나, 나이스에서 점수 정정이 있은 뒤 한쪽 파일만 다시 받은 경우입니다. 두 파일을 같은 시점에 다시 내려받아 보세요.", Caution="'정오표 없음(비교 불가)'는 그 반의 정오표 파일을 넣지 않았다는 뜻입니다." },
        };

        public static Term Get(string key) => Terms.FirstOrDefault(t => t.Key == key);

        // ---------- 수치 자동 해석 ----------
        public static string Discrimination(double d) =>
            d < 0 ? "음수: 정답·문항 점검 필요" : d < 0.10 ? "변별 거의 안 됨" : d < 0.20 ? "낮음(검토)" : d < 0.30 ? "보통" : d < 0.40 ? "좋음" : "매우 좋음";
        public static string PointBiserial(double r) =>
            r < 0 ? "음수: 점검" : r < 0.20 ? "낮음" : r < 0.30 ? "보통" : "좋음";
        public static string KR20(double a) =>
            a >= 0.90 ? "매우 높음" : a >= 0.80 ? "양호" : a >= 0.70 ? "보통(학교 시험으로 무난)" : a >= 0.60 ? "낮은 편(문항 점검 권장)" : "낮음";
        public static string Correlation(double r)
        {
            double a = Math.Abs(r);
            string s = a >= 0.70 ? "강한 관련" : a >= 0.40 ? "중간 정도 관련" : a >= 0.20 ? "약한 관련" : "거의 관련 없음";
            return r < 0 && a >= 0.2 ? s + "(반대 방향)" : s;
        }
        public static string Sd(double sd, double max) { double p = max > 0 ? sd / max * 100 : sd; return p <= 10 ? "점수가 고르게 모여 있음" : p <= 20 ? "보통 정도의 퍼짐" : "상·하위 차이가 매우 큼"; }
        public static string ItemVerdict(ItemStat it)
        {
            if (!it.Correct.HasValue) return "문항별 자료 없음";
            double d = it.Discrimination ?? 0, p = it.CorrectRate;
            string v;
            if (d < 0) v = "변별도 음수: 정답 입력·문항 오류를 꼭 확인";
            else if (p >= 0.95) v = "거의 전원 정답: 기본 개념 확인용 문항";
            else if (p < 0.25 && d < 0.2) v = "매우 어렵고 변별 안 됨: 문항 또는 수업 내용 점검";
            else if (p < 0.5 && d >= 0.3) v = "어렵지만 변별 좋음: 상위권을 가르는 문항";
            else if (d < 0.1) v = "변별 거의 안 됨: 선택지 점검";
            else if (d < 0.2) v = "변별도 낮음: 다듬으면 좋음";
            else if (p >= 0.8) v = "쉽고 양호: 기본 문항";
            else if (d >= 0.4) v = "매우 좋은 문항";
            else v = "양호";
            if (it.BlankRate + it.MultiRate >= 0.05) v += " / 무표기·복수답안 5% 이상(시간 부족이나 헷갈리는 문항인지 확인)";
            if (it.LevelInversion != null) v += " / " + it.LevelInversion.Split(':')[0] + "(성취도별 문항 시트 참고)";
            return v;
        }
    }
}
